    assertThat(first).contains("\"deviceId\":\"d1\"");

    String replay = registerDevice("rid-1", "d1", "m1", "1.0.0", 5);
    assertThat(replay).isEqualTo(first);
    assertThat(jdbc.queryForObject("SELECT COUNT(*) FROM device", Long.class)).isEqualTo(1);

